"""Exercise the actual native tree cut under independent local resume events."""
import re,json,pathlib
p=pathlib.Path('native');s=(p/'reset_cut.v').read_text();ports=re.search(r'input (.*); output',s)[1].split(',');clocks=ports[1:];m=json.load(open(p/'manifest.json'));fi=clocks.index('ck_fa4')
lines=['`timescale 1ns/1ps','module tb_a0_reset_cut;',f'reg [{len(clocks)-1}:0] ck=0;',f'reg [{len(clocks)-1}:0] run=0;','reg rs=0; wire [18:0] leaf; integer MUT=0; initial if($value$plusargs("MUT=%d",MUT))begin end', 'a0_actual_reset_cut dut (.rst_n(rs),'+','.join('.'+n+'(ck[%d])'%j for j,n in enumerate(clocks))+',.leaf(leaf));','reg [2:0] face=0;',f'always @(posedge ck[{fi}] or negedge rs) if(!rs) face<=0; else face<={{face[1:0],1\'b1}};','integer checks=0;']
for j in range(19):
 clock=next(r['clock'] for r in m['leaf_endpoints'] if r['leaf']==j);i=clocks.index(clock)
 lines += [f'reg expect_{j}=0; always @(posedge ck[{i}] or negedge face[2]) if(!face[2])expect_{j}<=0;else expect_{j}<=1;',f'always @(negedge ck[{i}]) begin checks=checks+1;if(leaf[{j}]!==expect_{j}) $fatal(1,"A0_RESET_CUT_TRACE_FAIL leaf{j} MUT%0d",MUT);end']
lines += ["initial begin #0.01;if(MUT==42)force dut.\\a0_reset_face1_q = rs; if(MUT==41)force dut.\\a0_reset_leaf_11_q = 1'b0; if(MUT==43)force dut.\\a0_reset_face1_q = 1'b1; if(MUT==44)force dut.\\a0_reset_branch_q = dut.\\a0_reset_face2_q ;end",'integer scenario,step,i;integer latest_ready;initial begin', '#0.1;rs=0;#0.1;rs=1;', 'for(scenario=0;scenario<32;scenario++)begin', ' run=0;ck=0;#0.1;rs=0;#0.1;', ' if(leaf!==0)$fatal(1,"A0_RESET_STOPPED_ASSERT_FAIL scenario%0d leaf%h",scenario,leaf);', '#0.1;rs=1;#0.1;if(leaf!==0)$fatal(1,"A0_RESET_STOPPED_RELEASE_FAIL");', ' latest_ready=-1;', ' for(step=0;step<160;step++)begin',f'  for(i=0;i<{len(clocks)};i++)begin', '   if(step>=((i+scenario)%17)*2)run[i]=1;', '   if(run[i] && ((step+i+scenario)%2==0))ck[i]=~ck[i];', '  end', '  #0.1;if(leaf===19\'h7ffff && latest_ready<0)latest_ready=step;', ' end', ' if(latest_ready<0)$fatal(1,"A0_RESET_RESUME_FAIL");', ' $display("A0_RESET_EPOCH scenario%0d ready_step%0d",scenario,latest_ready);', 'end', '$display("A0_RESET_CUT_PASS scenarios32 independent_clocks%d checks%0d",'+str(len(clocks))+',checks);$finish;end endmodule']
(p/'tb_cut.sv').write_text('\n'.join(lines)+'\n')
